"""Texto base para adopción por el responsable institucional; no presupone su identidad."""
import os
VERSION='2026-11-06.2'

def politica():
    name=os.environ.get('DATA_CONTROLLER_NAME','').strip()
    contact=os.environ.get('DATA_CONTROLLER_CONTACT','').strip()
    return {'version':VERSION,'titulo':'Política de tratamiento y protección de la información','entidad_operadora':'Asociación Amigos con Calor Humano','responsable':name or 'Por confirmar conforme al acuerdo aplicable entre el ICBF y la entidad operadora','contacto':contact or 'recepcion@asociacionamigos.org — canal general publicado; falta confirmar el canal específico de protección de datos','borrador':not bool(name and contact),'secciones':[
      {'titulo':'Finalidad','texto':'Gestionar la identificación, asignación, acompañamiento y seguimiento de niños, niñas y adolescentes atendidos en servicios de protección del ICBF, registrar avances y producir los informes del proceso. Los datos no se utilizarán para publicidad, campañas comerciales ni otros propósitos ajenos al servicio de protección.'},
      {'titulo':'Niños, niñas y adolescentes','texto':'El tratamiento debe respetar sus derechos fundamentales y su interés superior. La entidad verificará la representación, la autorización o fundamento aplicable y la participación del niño, niña o adolescente según corresponda. Solo se incorporará la información necesaria para la atención; no se divulgarán expedientes, identidades ni imágenes en el repositorio público.'},
      {'titulo':'Roles de la entidad y del ICBF','texto':'La Asociación Amigos con Calor Humano se identifica como entidad operadora indicada para esta app. Las funciones de responsable y encargado del tratamiento, los canales de derechos y las condiciones de almacenamiento se definirán conforme a los instrumentos institucionales aplicables con el ICBF; no se presumen por la propiedad de la cuenta de GitHub.'},
      {'titulo':'Ubicación de residencia','texto':'La ubicación se solicita solo al pulsar Capturar ubicación de la residencia, con permiso del dispositivo. Se guardan dirección, municipio, coordenadas, precisión, fecha y persona operadora que confirma la residencia. No se realiza seguimiento en segundo plano ni se incluyen coordenadas en el QR. El GPS corresponde al teléfono; la operadora debe confirmar que se encuentra en la residencia. La entidad debe verificar la necesidad y el fundamento de recolectar esta ubicación para el servicio.'},
      {'titulo':'Información reservada y sensible','texto':'Los expedientes pueden contener identificación, información familiar, de salud y del proceso de protección. El acceso se limita al personal autorizado según sus funciones. La administración técnica de la app no determina quién es el responsable jurídico del tratamiento.'},
      {'titulo':'Autorización y deber de confidencialidad','texto':'La entidad debe definir y documentar el fundamento aplicable al tratamiento y las autorizaciones que correspondan. La aceptación de esta política por una operadora es un compromiso de confidencialidad; no sustituye la autorización del titular ni las reglas institucionales para información de niños, niñas o personas representadas.'},
      {'titulo':'Derechos y solicitudes','texto':'Los titulares o sus representantes podrán solicitar conocer, actualizar y rectificar la información, consultar su uso y solicitar supresión o revocatoria cuando proceda. Las solicitudes se dirigirán al canal del responsable indicado arriba, que tramitará consultas y reclamos según la normativa aplicable.'},
      {'titulo':'Acceso y bloqueo','texto':'Cada persona operadora utiliza una cuenta individual y un PIN de cuatro dígitos. La app bloquea el acceso después de quince minutos sin actividad y limita intentos fallidos. Recuperar el PIN con la contraseña conserva el maestro y los seguimientos. No se comparten contraseñas ni se publica información de beneficiarios.'},
      {'titulo':'Almacenamiento y terceros','texto':'GitHub contendrá únicamente código público. El maestro se carga desde la app y sus registros se guardan en la base privada del servidor. Si se prepara el modo sin conexión, el dispositivo conserva una copia cifrada de los casos autorizados y registros pendientes hasta sincronizar; debe ser un equipo autorizado y protegido. Los informes descargados quedan bajo custodia de quien los descarga. Los proveedores de alojamiento y, si se utiliza, el servicio de dictado del navegador deben ser revisados y autorizados por la entidad antes de cargar información real.'},
      {'titulo':'Conservación, calidad e incidentes','texto':'El responsable definirá plazos de conservación, copias de seguridad, eliminación autorizada y atención de incidentes conforme al proceso. Los fallos documentales se registran para revisión sin corregir automáticamente el dato original. Se reportará cualquier acceso indebido o pérdida al canal institucional.'},
      {'titulo':'Vigencia','texto':'Versión '+VERSION+'. Texto base pendiente de adopción por la entidad responsable. Marco de referencia: Ley 1581 de 2012 y Decreto 1074 de 2015. Los datos de contacto, plazos institucionales y proveedores deben completarse antes del uso operativo.'}
    ],'fuentes':[{'titulo':'Ley 1581 de 2012','url':'https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=49981'},{'titulo':'SIC: política de tratamiento de datos','url':'https://sedeelectronica.sic.gov.co/politica-de-tratamiento-de-datos-personales'},{'titulo':'Asociación: transparencia y aviso legal','url':'https://www.asociacionamigos.org/transparencia/'},{'titulo':'Asociación: canal de contacto publicado','url':'https://www.asociacionamigos.org/contact-us/'}]}
